  right: 0;
  bottom: 1px;
  left: 0;
  z-index: 0;
  height: 0.5px;
  background: var(--dsw-alias-border-l3);
  pointer-events: none;
}

/* Blank hero/settling: keep the strict Session header mounted without taking
