  const rootRef = React.useRef(null)
  const triggerRef = React.useRef(null)
  const panelRef = React.useRef(null)

  // The panel is portaled to the body and placed from the trigger's viewport rect,
  // re-measured on scroll and resize while it is open.
  const position = useAnchoredPosition({ open, anchorRef: triggerRef, panelRef, side: 'bottom', gap: 8, margin: 12 })
  // The trigger and the open panel are two elements, so pass the panel as the portal root.
  useDismissOnOutsidePointer(rootRef, open, setOpen, panelRef)

