{"content": "// ACRYL local extension: header Note widget (browser half).
// Fills `conversation.session.header.actions` — the top bar of a conversation, next to its title —
// with a compact "Notes" button that opens a small panel anchored under it. Notes are written,
// saved and deleted in the panel and persist in localStorage. The panel is portaled to the body,
// so the header's own layout and overflow never clip it.
// No build step: hand-written CommonJS, React.createElement only, no JSX/import.
window.__ModuleLoader__.load({ id: 'acryl-header-note', factory: (require) => {
var module = { exports: {} }; var exports = module.exports;

const React = require('react')
const ReactDOM = require('react-dom')
const {
  Button,
  useAnchoredPosition,
  useDismissOnOutsidePointer,
  IconListPenOutline16,
  IconCloseOutline16,
  IconTrashOutline16,
} = require('@deepseek-ai/dsh-client-ui-primitives')

const h = React.createElement
const ID = 'acryl-header-note'
const STORAGE_KEY = ID + ':notes'
const MAX_NOTES = 200
console.info('[' + ID + '] client module loaded')

// Colors, radii and elevation come from the app's own popover layer (the menu/tooltip tokens),
// so the panel matches the theme in light and dark without any literal color.
const STYLES = `
.acryl-hnote-root { display: inline-flex; align-items: center; }
.acryl-hnote-count { margin-left: 6px; color: var(--dsw-alias-label-tertiary); font-size: 11px; line-height: 16px; font-variant-numeric: tabular-nums; }
.acryl-hnote-panel { position: fixed; z-index: 100; display: flex; flex-direction: column; width: 340px; max-width: calc(100vw - 24px); max-height: min(60vh, 460px); overflow: hidden; border: 0.5px solid var(--dsw-alias-border-l4); border-radius: 12px; background: var(--dsw-specific-menu); box-shadow: var(--dsw-elevation-prominent); }
.acryl-hnote-header { display: flex; align-items: center; justify-content: space-between; gap: 8px; flex: none; min-height: 44px; padding: 8px 8px 8px 12px; }
.acryl-hnote-title { color: var(--dsw-alias-label-primary); font-size: 14px; font-weight: 500; line-height: 20px; }
.acryl-hnote-body { display: flex; flex-direction: column; gap: 12px; flex: 1; min-height: 0; padding: 0 12px 12px; overflow-y: auto; --dsh-scrollbar-thumb: var(--dsw-alias-scrollbar-bg-l2); --dsh-scrollbar-thumb-hover: var(--dsw-alias-scrollbar-hover-l2); }
.acryl-hnote-input { box-sizing: border-box; width: 100%; min-height: 72px; padding: 8px; border: 0.5px solid var(--dsw-alias-border-l4); border-radius: 8px; background: var(--dsw-alias-bg-layer-1); color: var(--dsw-alias-label-primary); font-family: inherit; font-size: 14px; line-height: 22px; resize: vertical; outline: none; }
.acryl-hnote-input::placeholder { color: var(--dsw-alias-label-dimmed); }
.acryl-hnote-input:focus { border-color: var(--dsw-alias-brand-primary); }
.acryl-hnote-actions { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.acryl-hnote-hint { color: var(--dsw-alias-label-tertiary); font-size: 12px; line-height: 18px; }
.acryl-hnote-empty { margin: 0; color: var(--dsw-alias-label-tertiary); font-size: 12px; line-height: 18px; }
.acryl-hnote-list { display: flex; flex-direction: column; gap: 8px; margin: 0; padding: 0; list-style: none; }
.acryl-hnote-item { display: flex; flex-direction: column; gap: 4px; padding: 10px 8px 10px 12px; border: 0.5px solid var(--dsw-alias-border-l4); border-radius: 12px; }
.acryl-hnote-itemHead { display: flex; align-items: center; justify-content: space-between; gap: 8px; min-height: 28px; }
.acryl-hnote-time { color: var(--dsw-alias-label-tertiary); font-size: 11px; line-height: 16px; }
.acryl-hnote-text { margin: 0; color: var(--dsw-alias-label-primary); font-size: 13px; line-height: 20px; white-space: pre-wrap; overflow-wrap: anywhere; }
`

/** Read the saved notes, tolerating absent or corrupted storage. */
function loadNotes() {
  try {
    const parsed = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]')
    if (!Array.isArray(parsed)) return []
    return parsed.filter(note => note !== null && typeof note === 'object' && typeof note.text === 'string')
  } catch {
    return []
  }
}

/** Short local timestamp for one saved note. */
function noteTime(at) {
  const date = new Date(at)
  if (Number.isNaN(date.getTime())) return ''
  return date.toLocaleString(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })
}

function HeaderNote() {
  const [open, setOpen] = React.useState(false)
  const [notes, setNotes] = React.useState(loadNotes)
  const [draft, setDraft] = React.useState('')
  const rootRef = React.useRef(null)
  const triggerRef = React.useRef(null)
  const panelRef = React.useRef(null)

  // The panel hangs from the trigger's viewport rect and is re-placed on resize, on scroll
  // (capture phase, so nested scrollers count) and when its own size changes.
  const position = useAnchoredPosition({ open, anchorRef: triggerRef, panelRef, side: 'bottom', gap: 8, margin: 12 })
  // The trigger and the portaled panel are separate elements, so the panel is passed as the
  // portal root that also counts as inside.
  useDismissOnOutsidePointer(rootRef, open, setOpen, panelRef)

  React.useEffect(() => {
    if (!open) return undefined
    const onKey = event => {
      if (event.key !== 'Escape') return
